function solution(value, min, max) {
  if (min > max) {
    throw new RangeError("min must not be greater than max");
  }

  return Math.min(Math.max(value, min), max);
}

function solution(value, min, max) {
  if (min > max) {
    throw new RangeError("min must not exceed max");
  }
  return Math.min(max, Math.max(min, value));
}

function solution(value, min, max) {
  if (min > max) {
    throw new RangeError("min must be less than or equal to max");
  }

  return Math.min(Math.max(value, min), max);
}

function solution(intervals) {
  const sorted = intervals.map(([start, end]) =>
    start <= end ? [start, end] : [end, start]
  );
  sorted.sort((a, b) => a[0] - b[0]);

  const merged = [];
  for (const interval of sorted) {
    const previous = merged[merged.length - 1];
    if (previous && interval[0] <= previous[1]) {
      previous[1] = Math.max(previous[1], interval[1]);
    } else {
      merged.push(interval);
    }
  }
  return merged;
}

function solution(intervals) {
  if (intervals.length === 0) return [];

  const normalized = intervals.map(([start, end]) =>
    start <= end ? [start, end] : [end, start]
  );

  normalized.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  const merged = [normalized[0].slice()];
  for (let i = 1; i < normalized.length; i += 1) {
    const current = normalized[i];
    const last = merged[merged.length - 1];

    if (current[0] <= last[1]) {
      last[1] = Math.max(last[1], current[1]);
    } else {
      merged.push(current.slice());
    }
  }

  return merged;
}

function solution(intervals) {
  if (intervals.length === 0) return [];

  const normalized = intervals.map(function (interval) {
    const start = interval[0];
    const end = interval[1];
    return start <= end ? [start, end] : [end, start];
  });

  normalized.sort(function (a, b) {
    return a[0] - b[0] || a[1] - b[1];
  });

  const merged = [normalized[0]];
  for (let i = 1; i < normalized.length; i += 1) {
    const current = normalized[i];
    const last = merged[merged.length - 1];

    if (current[0] <= last[1]) {
      if (current[1] > last[1]) last[1] = current[1];
    } else {
      merged.push(current);
    }
  }

  return merged;
}

function solution(initial, operations) {
  const balances = {};
  const accountNames = Object.getOwnPropertyNames(initial);

  // Define properties explicitly so account names such as "__proto__" remain
  // ordinary ledger accounts instead of invoking Object.prototype setters.
  for (const name of accountNames) {
    Object.defineProperty(balances, name, {
      value: initial[name],
      writable: true,
      enumerable: true,
      configurable: true
    });
  }

  const appliedIds = new Set();
  const statuses = [];

  for (const operation of operations) {
    const id = operation.id;

    if (appliedIds.has(id)) {
      statuses.push("duplicate");
      continue;
    }

    const from = operation.from;
    const to = operation.to;
    const amount = operation.amount;
    const hasFrom = Object.prototype.hasOwnProperty.call(balances, from);
    const hasTo = Object.prototype.hasOwnProperty.call(balances, to);
    const validAmount = Number.isSafeInteger(amount) && amount > 0;

    if (!hasFrom || !hasTo || !validAmount) {
      statuses.push("rejected");
      continue;
    }

    const sourceBalance = balances[from];

    if (sourceBalance < amount) {
      statuses.push("rejected");
      continue;
    }

    if (from === to) {
      // The destination is also the source, so its resulting balance is
      // unchanged; importantly, no overflowing intermediate sum is needed.
      appliedIds.add(id);
      statuses.push("applied");
      continue;
    }

    const destinationBalance = balances[to];
    const resultingDestinationBalance = destinationBalance + amount;

    if (!Number.isSafeInteger(resultingDestinationBalance)) {
      statuses.push("rejected");
      continue;
    }

    // All validation is complete before either account is changed.
    balances[from] = sourceBalance - amount;
    balances[to] = resultingDestinationBalance;
    appliedIds.add(id);
    statuses.push("applied");
  }

  return { balances, statuses };
}

function solution(initial, operations) {
  var hasOwn = Object.prototype.hasOwnProperty;
  var balances = Object.create(null);

  Object.keys(initial).forEach(function (account) {
    balances[account] = initial[account];
  });

  var appliedIds = new Set();
  var statuses = [];

  operations.forEach(function (operation) {
    var id = operation.id;

    if (appliedIds.has(id)) {
      statuses.push("duplicate");
      return;
    }

    var from = operation.from;
    var to = operation.to;
    var amount = operation.amount;
    var valid =
      hasOwn.call(initial, from) &&
      hasOwn.call(initial, to) &&
      Number.isSafeInteger(amount) &&
      amount > 0;

    if (valid) {
      var sourceBalance = balances[from];
      var destinationBalance = balances[to];

      valid = sourceBalance >= amount;

      if (valid && from !== to) {
        valid =
          Number.isSafeInteger(sourceBalance - amount) &&
          Number.isSafeInteger(destinationBalance + amount);

        if (valid) {
          balances[from] = sourceBalance - amount;
          balances[to] = destinationBalance + amount;
        }
      }
    }

    if (valid) {
      appliedIds.add(id);
      statuses.push("applied");
    } else {
      statuses.push("rejected");
    }
  });

  var resultBalances = {};
  Object.keys(balances).forEach(function (account) {
    Object.defineProperty(resultBalances, account, {
      value: balances[account],
      enumerable: true,
      writable: true,
      configurable: true
    });
  });

  return { balances: resultBalances, statuses: statuses };
}

function solution(initial, operations) {
  const balances = {};
  for (const account of Object.getOwnPropertyNames(initial)) {
    Object.defineProperty(balances, account, {
      value: initial[account],
      writable: true,
      enumerable: true,
      configurable: true
    });
  }

  const appliedIds = new Set();
  const statuses = [];
  const hasAccount = account =>
    Object.prototype.hasOwnProperty.call(balances, account);

  for (const operation of operations) {
    const id = operation.id;
    if (appliedIds.has(id)) {
      statuses.push("duplicate");
      continue;
    }

    const { from, to, amount } = operation;
    if (!hasAccount(from) || !hasAccount(to) ||
        !Number.isSafeInteger(amount) || amount <= 0 ||
        balances[from] < amount) {
      statuses.push("rejected");
      continue;
    }

    // A self-transfer leaves the balance unchanged, even near the safe limit.
    if (from !== to) {
      const destinationBalance = balances[to] + amount;
      if (!Number.isSafeInteger(destinationBalance)) {
        statuses.push("rejected");
        continue;
      }
      balances[from] -= amount;
      balances[to] = destinationBalance;
    }

    appliedIds.add(id);
    statuses.push("applied");
  }

  return { balances, statuses };
}
